<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue'
const canvas=ref<HTMLCanvasElement|null>(null);let raf=0;let resize=()=>{};let move=(event:Event)=>{}
onMounted(()=>{const c=canvas.value,ctx=c?.getContext('2d');if(!c||!ctx)return;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,mobile=innerWidth<700,stars=Array.from({length:reduced?40:mobile?95:165},()=>({x:Math.random(),y:Math.random(),s:Math.random()*1.4+.2,z:Math.random()}));let p={x:.5,y:.5};resize=()=>{const d=Math.min(devicePixelRatio,mobile?1.5:2);c.width=innerWidth*d;c.height=innerHeight*d;c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';ctx.setTransform(d,0,0,d,0,0)};move=(event:Event)=>{const e=event as PointerEvent;p={x:e.clientX/innerWidth,y:e.clientY/innerHeight}};const draw=(t:number)=>{ctx.clearRect(0,0,innerWidth,innerHeight);const h=ctx.createRadialGradient(innerWidth*.5,innerHeight*.26,0,innerWidth*.5,innerHeight*.26,innerWidth*.72);h.addColorStop(0,'rgba(115,130,255,.1)');h.addColorStop(1,'transparent');ctx.fillStyle=h;ctx.fillRect(0,0,innerWidth,innerHeight);stars.forEach((a,i)=>{ctx.fillStyle=`rgba(224,231,255,${(reduced?1:.5+Math.sin(t/900+i)*.3)*a.z})`;ctx.beginPath();ctx.arc(a.x*innerWidth+(p.x-.5)*a.z*12,a.y*innerHeight+(p.y-.5)*a.z*12,a.s,0,7);ctx.fill()});raf=requestAnimationFrame(draw)};resize();addEventListener('resize',resize);addEventListener('pointermove',move,{passive:true});raf=requestAnimationFrame(draw)})
onBeforeUnmount(()=>{cancelAnimationFrame(raf);removeEventListener('resize',resize);removeEventListener('pointermove',move)})
</script><template><canvas ref="canvas" class="star-field" aria-hidden="true"/></template>
